'use strict';
(() => {
  const studies = {
    rides: {
      category:'01 / BUSINESS INTELLIGENCE',title:'RIDE-SHARING ANALYTICS',subtitle:'SQL, Excel, and Power BI / Résumé project',
      description:'A complete analytics workflow for a ride-sharing dataset — cleaning the raw records, answering business questions with SQL, and bringing the findings together in an interactive Power BI dashboard.',
      metrics:[['100K+','Dataset rows analyzed'],['19','Columns in the dataset'],['5','Interactive dashboard pages']],
      tools:['SQL','Excel','Power BI','DAX','Power Query'],
      challenge:'A large ride-sharing dataset contains many connected business questions: how bookings progress, where cancellations occur, how revenue varies, and what the customer experience looks like. The work focused on organizing those questions into a clear analytical view.',
      deliverables:['Cleaned and prepared dataset with missing values, duplicates, and inconsistent formats addressed.','SQL business analysis using joins, CTEs, subqueries, CASE statements, aggregations, and window functions.','Reusable SQL Views for frequently used analytical results.','Five-page Power BI dashboard with booking, cancellation, revenue, payment, vehicle, and customer-rating KPIs.'],
      method:[['Clean','Build a trustworthy starting point.','Used Excel to prepare the raw dataset, working through missing values, duplicate records, inconsistent formatting, and data-quality issues before analysis.'],['Query','Ask the business questions.','Used SQL joins, CTEs, subqueries, CASE expressions, aggregations, and window functions to explore booking, cancellation, revenue, payment, vehicle-type, distance, and rating trends. Reusable Views organized frequently used results.'],['Model','Connect the analytical pieces.','Used Power Query and data modeling to support interactive reporting. DAX measures calculated total bookings and cancellation percentages.'],['Visualize','Make the findings easier to explore.','Created a five-page Power BI dashboard bringing the operational and customer-experience KPIs together. The emphasis was on presenting trends clearly and communicating useful analytical insights.']]
    },
    ipl: {
      category:'02 / SPORTS ANALYTICS & MACHINE LEARNING',title:'IPL CRICKET ANALYTICS',subtitle:'Ball-by-ball analysis & post-toss prediction / Expanded project',
      description:'A reproducible exploration of 19 IPL seasons: from match-level records to player statistics, scoring patterns, and a carefully evaluated post-toss win predictor. The original 577-match project expands to a documented 1,243-match Cricsheet snapshot.',
      metrics:[['1,243','Matches in the source snapshot'],['19','Seasons covered · 2008–2026'],['295,732','Delivery events, including Super Overs']],
      tools:['Python','Pandas','NumPy','scikit-learn','Matplotlib','Jupyter'],
      challenge:'How do team history, venue, toss, and scoring patterns relate to match outcomes? This project connects descriptive cricket analysis with a chronological prediction experiment, while keeping source coverage, cricket-specific definitions, and model limitations visible.',
      deliverables:['Normalized match, delivery, innings, wicket, and player-appearance datasets, with source provenance and documented cricket rules.','Career and season batting/bowling statistics; team, venue, toss, and scoring-phase analysis; eight original charts.','Logistic regression and random-forest comparison using historical Elo, recent form, head-to-head, scoring rate, team experience, venue, and toss features.','Executed notebook, portable HTML report, saved predictions and models, methodology, and a complete downloadable source package.'],
      method:[['Prepare','Preserve the details that matter.','Parse the Cricsheet JSON snapshot into five linked datasets. Keep distinct franchises separate, preserve no-result matches for coverage, and flag Super Overs. All 577 original matches reconcile by date and teams, with no winner differences.'],['Engineer','Use only information available at the time.','Create Elo, recent win and scoring form, head-to-head, and experience features using earlier dates only. Fit one-hot encodings on training data. Toss information makes this a post-toss model; current-match outcomes and same-day results are excluded.'],['Explore','Move from deliveries to a clearer story.','Analyze player career and season performance, team wins, venue patterns, toss/chasing associations, and scoring phases. Cricket denominators are explicit: legal balls, balls faced, and bowler-credit wickets follow different rules.'],['Evaluate','Test on a later season. Report the result.','Train through 2024, select the model using 2025 validation log loss, then test on 73 decided matches in 2026. The random forest records 45.21% accuracy and 0.6867 log loss. Test-season history updates after earlier dates while model weights stay fixed.']]
    }
  };
  const escape = text => String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const iplCharts = [
    ['scoring_trend','First-innings scoring','Average first-innings runs in eligible completed, scheduled 20-over innings. Rain-method results are excluded; full inclusion rules are in the methodology.'],
    ['phase_scoring','Scoring by phase','Run rates across fixed overs 1–6, 7–15, and 16–20. Super Overs, recorded rain-method matches, and scheduled shortened innings are excluded.'],
    ['season_coverage','Season coverage','Matches present in the supplied Cricsheet snapshot, not an official fixture count.'],
    ['team_wins_barh','Team wins','Historical team wins in the source snapshot. Franchise renames are normalized; distinct franchises remain separate.'],
    ['batting_barh','Leading batters','Career runs in the supplied source coverage, excluding Super Overs.'],
    ['bowling_barh','Leading bowlers','Bowler-credit wickets in the supplied source coverage, excluding Super Overs.'],
    ['confusion_matrix','Model predictions','Confusion matrix for the fixed holdout model on 73 decided matches in the 2026 test season.'],
    ['calibration','Probability calibration','Predicted probabilities compared with observed outcomes in the small held-out test sample.']
  ];
  function iplEvidence(){return `<section class="ipl-evidence" aria-labelledby="ipl-evidence-title"><div class="ipl-section-heading"><span class="study-eyebrow">FROM THE DELIVERED PROJECT</span><h3 id="ipl-evidence-title">The numbers behind the story.</h3><p>Source coverage: 18 April 2008 – 31 May 2026. Snapshot retrieved 14 October 2026.</p></div><div class="ipl-findings"><article><strong>54.39<span>%</span></strong><h4>Chasing teams won</h4><p>650 of 1,195 eligible regulation matches; excludes ties, Super Overs, and recorded rain-method results.</p></article><article><strong>51.38<span>%</span></strong><h4>Toss winners also won</h4><p>634 of 1,234 decided matches. A historical association, not evidence that winning the toss causes victory.</p></article><article><strong>10.07</strong><h4>Runs per over at the death</h4><p>Versus 8.08 in overs 1–6 and 7.94 in overs 7–15, under the project’s documented phase definitions.</p></article></div><div class="ipl-chart-head"><h4>Explore the analysis</h4><label for="ipl-chart-select">Choose a chart<select id="ipl-chart-select">${iplCharts.map((chart,i)=>`<option value="${i}">${chart[1]}</option>`).join('')}</select></label></div><figure class="ipl-chart"><img id="ipl-chart-image" src="assets/ipl/scoring_trend.png" alt="First-innings scoring by season" width="1574" height="853" loading="lazy"><figcaption id="ipl-chart-caption"></figcaption></figure><a class="ipl-chart-download" id="ipl-chart-download" href="assets/ipl/scoring_trend.png" download>Download this chart ↓</a><div class="ipl-model"><div><span class="study-eyebrow">THE PREDICTION EXPERIMENT</span><h3>Honest evaluation.<br>Useful lessons.</h3><p>A random forest selected on 2025 validation log loss, evaluated on 73 decided 2026 matches. These figures describe the saved holdout model, not the later all-data refit.</p><div class="ipl-timeline"><span><b>2008–2024</b>Train</span><span><b>2025</b>Select</span><span><b>2026</b>Test</span></div></div><div><div class="demo-table-wrap"><table class="demo-table ipl-results"><caption>2026 holdout results</caption><thead><tr><th scope="col">MEASURE</th><th scope="col">MODEL</th><th scope="col">BASELINE*</th></tr></thead><tbody><tr><th scope="row">Accuracy</th><td>45.21%</td><td>42.47%</td></tr><tr><th scope="row">Log loss ↓</th><td>0.6867</td><td>0.6946</td></tr><tr><th scope="row">Brier score ↓</th><td>0.2472</td><td>0.2507</td></tr><tr><th scope="row">ROC AUC</th><td>0.4800</td><td>0.5000</td></tr></tbody></table></div><p class="ipl-small">*Baseline uses the earlier training-period class prior. Lower log loss and Brier score are better.</p><p class="ipl-model-limit">Predictive performance is modest and uncertain: the approximate 95% accuracy interval is 34.31%–56.58%. Lineups, injuries, weather, and pitch forecasts are not included.</p></div></div><div class="ipl-downloads"><div><span class="study-eyebrow">OPEN THE COMPLETE WORK</span><h3>Go beyond the overview.</h3><p>Read the report, inspect the executed notebook, or download the complete project with its data, code, models, and documentation.</p></div><div class="ipl-download-links"><a href="assets/ipl/IPL_Analytics_Report.html" target="_blank" rel="noopener noreferrer">Read the full report <span>↗</span></a><a href="assets/ipl/IPL_Cricket_Analytics.ipynb" download>Download notebook <span>↓</span></a><a href="assets/ipl/ipl-cricket-analytics-complete.zip" download>Download complete project <small>9.8 MB</small><span>↓</span></a></div></div><p class="ipl-attribution">Data: <a href="https://cricsheet.org/downloads/" target="_blank" rel="noopener noreferrer">Cricsheet / Stephen Rushe</a>, under <a href="https://cricsheet.org/licensing/" target="_blank" rel="noopener noreferrer">ODC-By 1.0</a>. Derived tables normalize names and calculate statistics; original notices are preserved. Source coverage may omit unplayed fixtures. No Cricsheet endorsement is implied. <a href="assets/ipl/METHODOLOGY.md" download>Methodology ↓</a> · <a href="assets/ipl/source_manifest.json" download>Source manifest ↓</a></p></section>`;}
  $$('[data-project]').forEach(button=>button.addEventListener('click',()=>{
    const key=button.dataset.project,data=studies[key];
    $('#dialog-category').textContent=data.category;
    $('#dialog-content').innerHTML=`<div class="study-intro"><span class="study-eyebrow">${data.subtitle}</span><h2 id="dialog-title">${data.title}</h2><p>${data.description}</p><div class="technology-tags">${data.tools.map(t=>`<span>${escape(t)}</span>`).join('')}</div></div><div class="study-stats ${key==='ipl'?'navy':''}">${data.metrics.map(([value,label])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="study-body"><div class="study-story"><div><h3>THE QUESTION</h3><p>${data.challenge}</p></div><div><h3>WHAT I BUILT</h3><ul>${data.deliverables.map(t=>`<li>${t}</li>`).join('')}</ul></div></div><h3 class="method-title">EXPLORE THE WORKFLOW</h3><div class="method-tabs" role="group" aria-label="Project workflow">${data.method.map((m,i)=>`<button data-step="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${m[0]}</button>`).join('')}</div><div class="method-detail" id="workflow-detail" aria-live="polite"></div></div><div class="study-bottom"><span>RÉSUMÉ PROJECT / CUSTOM ILLUSTRATIVE COVER</span><div class="study-actions"><a href="assets/shameek-vardhan-bhatt-resume.pdf" download>Download résumé ↓</a><a href="https://github.com/Shameek4" target="_blank" rel="noopener noreferrer">GitHub profile ↗</a></div></div>`;
    if(key==='ipl'){
      $('.study-bottom',projectDialog).insertAdjacentHTML('beforebegin',iplEvidence());
      $('.study-bottom>span',projectDialog).textContent='EXPANDED PROJECT / SOURCE SNAPSHOT & SAVED RESULTS';
      const changeChart=()=>{const chart=iplCharts[Number($('#ipl-chart-select').value)],path='assets/ipl/'+chart[0]+'.png';$('#ipl-chart-image').src=path;$('#ipl-chart-image').alt=chart[1];$('#ipl-chart-caption').textContent=chart[2];$('#ipl-chart-download').href=path;};
      $('#ipl-chart-select').addEventListener('change',changeChart);changeChart();
    }
    function selectStep(i){const step=data.method[i];$('#workflow-detail').innerHTML=`<h4>${step[1]}</h4><p>${step[2]}</p>`;$$('[data-step]',projectDialog).forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===i)));}
    $$('[data-step]',projectDialog).forEach(b=>b.addEventListener('click',()=>selectStep(Number(b.dataset.step))));selectStep(0);
    openDialog(projectDialog,button);projectDialog.scrollTop=0;
  }));
})();
